from fastapi import FastAPI
from fastapi.responses import JSONResponse
from fastapi.testclient import TestClient


def test_default_response_headers_applied_to_route() -> None:
    app = FastAPI()

    @app.get(
        "/cached-item",
        default_response_headers={
            "Cache-Control": "max-age=300",
            "X-Source": "db",
        },
    )
    def get_cached_item() -> dict[str, int]:
        return {"id": 1}

    client = TestClient(app)
    response = client.get("/cached-item")

    assert response.status_code == 200
    assert response.headers["cache-control"] == "max-age=300"
    assert response.headers["x-source"] == "db"


def test_handler_explicit_header_overrides_default() -> None:
    app = FastAPI()

    @app.get(
        "/override",
        default_response_headers={
            "Cache-Control": "max-age=300",
            "X-Source": "db",
        },
    )
    def get_with_explicit_cache_control() -> JSONResponse:
        response = JSONResponse({"id": 2})
        response.headers["Cache-Control"] = "no-store"
        return response

    client = TestClient(app)
    response = client.get("/override")

    assert response.status_code == 200
    # The handler's explicit Cache-Control must win over the route default.
    assert response.headers["cache-control"] == "no-store"
    # Other headers from the default set that the handler did not touch
    # are still applied.
    assert response.headers["x-source"] == "db"


def test_no_default_headers_is_backwards_compatible() -> None:
    app = FastAPI()

    @app.get("/plain")
    def get_plain() -> dict[str, str]:
        return {"hello": "world"}

    client = TestClient(app)
    response = client.get("/plain")

    assert response.status_code == 200
    assert response.json() == {"hello": "world"}
    # Without default_response_headers, the route is not modified.
    assert "x-source" not in response.headers

